/**
 * The public album's data contract.
 *
 * ## Why this file exists apart from the data
 *
 * Everything downstream — stats, map, timeline, search, the pages — consumes
 * these shapes, and only `src/data/album.ts` produces them. Keeping the types in
 * `lib/` means the writer (hand-written today, generated by the publish pipeline
 * later) can be swapped without any consumer noticing, and a field rename fails
 * at the one place that defines it.
 *
 * ## What is deliberately absent
 *
 * No `visibility` and no `status`. The published data contains **only** photos
 * that are already public and active (spec §5.1): filtering belongs to the
 * publisher, not to the page. A page that re-filters would be a second, silent
 * opinion about what is public — exactly the class of bug the spec rules out.
 */

export interface Place {
  id: string
  /** Chinese name, shown on the zh site and used as the search key. */
  name: string
  /** English name, shown on the en site. Empty falls back to `name`. */
  nameEn: string
  lat: number
  lon: number
}

export interface Photo {
  id: string
  /** Public path to the webp, e.g. `/album/2023/m2x1.webp`. */
  src: string
  width: number
  height: number
  /** Base64 32px blur placeholder for `next/image`. */
  blur: string
  /** ISO8601 with the original offset; `null` when the camera had no clock. */
  takenAt: string | null
  /** `YYYY-MM`, precomputed so the timeline never parses dates. `null` like `takenAt`. */
  bucket: string | null
  /** True when `takenAt` fell back to the file's modification time. */
  takenEstimated?: boolean
  /** `Place.id`, or `null` for a photo with no coordinates (a screenshot). */
  placeId: string | null
  /** The one line the owner wrote. The only description ever displayed. */
  caption?: string
  albumIds: readonly string[]
  /** Concept ids from `lib/album/concepts.ts`, not free text. */
  tags: readonly string[]
}

export interface Album {
  id: string
  slug: string
  title: string
  titleEn: string
  description?: string
  /** `Photo.id` used as the cover. */
  coverId?: string
  photoIds: readonly string[]
}

export interface AlbumData {
  photos: readonly Photo[]
  places: readonly Place[]
  albums: readonly Album[]
}
